import threading, time, sys
from cache import Cache


def test_shared_single_load_and_timeout():
    c = Cache(); calls = []; barrier = threading.Barrier(3); results = []
    def loader():
        calls.append(1); time.sleep(0.1); return 7
    def worker():
        barrier.wait(); results.append(c.get("a", loader))
    ts = [threading.Thread(target=worker) for _ in range(2)]
    [t.start() for t in ts]; barrier.wait()
    [t.join(timeout=2) for t in ts]
    assert results == [7, 7], results
    assert len(calls) == 1, calls
    assert all(not t.is_alive() for t in ts)


def test_distinct_keys_independent():
    c = Cache(); active = []; peak = [0]; lock = threading.Lock()
    def loader(name):
        def f():
            with lock:
                active.append(name); peak[0] = max(peak[0], len(active))
            time.sleep(0.1)
            with lock:
                active.remove(name)
            return name.upper()
        return f
    res = {}
    ts = [threading.Thread(target=lambda k=k: res.__setitem__(k, c.get(k, loader(k)))) for k in ("a", "b")]
    [t.start() for t in ts]; [t.join(timeout=2) for t in ts]
    assert res == {"a": "A", "b": "B"}, res
    assert peak[0] == 2, peak  # both loads ran concurrently


def test_failure_not_cached_and_retry():
    c = Cache(); boom = RuntimeError("boom")
    def bad():
        raise boom
    try:
        c.get("a", bad)
        raise AssertionError("expected failure")
    except RuntimeError as e:
        assert e is boom
    assert "a" not in c.values
    assert c.get("a", lambda: 5) == 5
    assert c.values["a"] == 5


def test_concurrent_failure_not_blocked_and_shared():
    c = Cache(); boom = RuntimeError("boom"); calls = []; barrier = threading.Barrier(3); errors = []
    def bad():
        calls.append(1); time.sleep(0.1); raise boom
    def worker():
        barrier.wait()
        try:
            c.get("a", bad)
        except RuntimeError as e:
            errors.append(e)
    ts = [threading.Thread(target=worker) for _ in range(2)]
    [t.start() for t in ts]; barrier.wait()
    [t.join(timeout=2) for t in ts]
    assert all(not t.is_alive() for t in ts), "callers blocked after failure"
    assert errors == [boom, boom], errors
    assert len(calls) == 1, calls
    assert "a" not in c.values
    assert c.get("a", lambda: 9) == 9


def test_retry_after_shared_failure():
    c = Cache(); state = {"fail": True}
    def loader():
        if state["fail"]:
            raise ValueError("nope")
        return 42
    try:
        c.get("k", loader); raise AssertionError
    except ValueError:
        pass
    state["fail"] = False
    assert c.get("k", loader) == 42


for name, fn in sorted(globals().items()):
    if name.startswith("test_") and callable(fn):
        fn(); print("ok", name)
print("ALL VALIDATION PASSED")
