import threading, random, time
from cache import Cache

# Stress 1: many threads, one key, one load.
for trial in range(50):
    c = Cache(); calls = []; N = 25; barrier = threading.Barrier(N)
    def loader():
        calls.append(1); time.sleep(random.random()*0.01); return 123
    res = []
    def w():
        barrier.wait(); res.append(c.get("k", loader))
    ts = [threading.Thread(target=w) for _ in range(N)]
    [t.start() for t in ts]; [t.join(timeout=5) for t in ts]
    assert all(not t.is_alive() for t in ts), "blocked"
    assert res == [123]*N and len(calls) == 1, (len(calls), len(res))
print("stress single-load ok")

# Stress 2: many distinct keys, each loaded once, all independent.
for trial in range(20):
    c = Cache(); lock = threading.Lock(); counts = {}
    def make(k):
        def f():
            with lock: counts[k] = counts.get(k, 0) + 1
            time.sleep(0.005); return k*2
        return f
    results = {}
    def w(k):
        results[k] = c.get(k, make(k))
    keys = list(range(15))
    ts = [threading.Thread(target=w, args=(k,)) for k in keys]
    [t.start() for t in ts]; [t.join(timeout=5) for t in ts]
    assert results == {k: k*2 for k in keys}
    assert all(v == 1 for v in counts.values()) and len(counts) == 15, counts
print("stress distinct-keys ok")

# Stress 3: failures never cached, retries eventually succeed.
for trial in range(50):
    c = Cache(); state = {"n": 0}
    def loader():
        state["n"] += 1
        if state["n"] < 3: raise RuntimeError("x")
        return "ok"
    for _ in range(2):
        try: c.get("k", loader); raise AssertionError
        except RuntimeError: pass
    assert c.get("k", loader) == "ok"
    assert c.values["k"] == "ok"
print("stress retry ok")
print("ALL STRESS PASSED")
